head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:        Sugarcoat
Version:     1.0.0
-----------------------------------------------

<Variable name="keycolor" description="Main Color" type="color" default="#1f4f46" value="#1f4f46"/>
<Group description="Theme Colors" selector="body">
<Variable name="body.background.color" description="Background" type="color" default="#f6f6f4" value="#f6f6f4"/>
<Variable name="body.text.color" description="Text" type="color" default="#222222" value="#222222"/>
<Variable name="posts.title.color" description="Title" type="color" default="#111111" value="#111111"/>
<Variable name="main.color" description="Accent" type="color" default="#1f4f46" value="#1f4f46"/>
</Group>
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="16px IBM Plex Sans KR, sans-serif" value="16px IBM Plex Sans KR, sans-serif"/>
<Variable name="posts.background.color" description="Surface" hideEditor="true" type="color" default="#ffffff" value="#ffffff"/>
*/

:root {
  --bg: #f6f6f4;
  --surface: #ffffff;
  --text: #222222;
  --text-strong: #111111;
  --text-muted: #6b6b6b;
  --line: #ebebe8;
  --line-strong: #d8d8d4;
  --accent: #1f4f46;
  --ad-bg: #fafaf8;
  --ad-line: #e3e3de;
  --header-h: 64px;
  --content: 720px;
  --sidebar: 280px;
  --shell: 1080px;
  --gap: 40px;
  --radius: 8px;
  --font: "IBM Plex Sans KR", "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  color: var(--text);
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.7;
  letter-spacing: -0.01em;
  word-break: keep-all;
  overflow-wrap: break-word;
}

img, video, iframe { max-width: 100%; }
img { height: auto; vertical-align: middle; }
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button { cursor: pointer; }

.sr-only,
.skip-link {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.skip-link:focus {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 1200;
  width: auto;
  height: auto;
  padding: 8px 12px;
  clip: auto;
  color: #fff;
  background: #111;
  border-radius: 4px;
}

.reading-progress {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1100;
  height: 2px;
  background: transparent;
}

.reading-progress span {
  display: block;
  width: 0;
  height: 100%;
  background: var(--accent);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 900;
  height: var(--header-h);
  background: rgba(255, 255, 255, 0.94);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(8px);
}

.site-header__inner {
  display: flex;
  gap: 20px;
  align-items: center;
  max-width: var(--shell);
  height: 100%;
  padding: 0 20px;
  margin: 0 auto;
}

.brand {
  min-width: 0;
  flex: 0 1 auto;
}

.brand__title {
  display: block;
  overflow: hidden;
  color: var(--text-strong);
  font-size: 18px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.04em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.brand__desc { display: none; }

.site-nav {
  flex: 1 1 auto;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.site-nav::-webkit-scrollbar { display: none; }

.site-nav ul,
.site-nav li {
  margin: 0;
  padding: 0;
  list-style: none;
}

.site-nav ul {
  display: flex;
  gap: 4px;
  align-items: center;
}

.site-nav a {
  display: inline-flex;
  align-items: center;
  min-height: 36px;
  padding: 0 10px;
  color: #555;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  border-radius: 6px;
}

.site-nav a:hover,
.site-nav .selected a {
  color: #111;
  background: #f2f2ef;
}

.header-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-left: auto;
}

.search-form {
  display: flex;
  width: 210px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.search-form input {
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  color: var(--text);
  background: transparent;
  border: 0;
  outline: 0;
}

.search-form button,
.search-form input[type="submit"] {
  padding: 8px 12px;
  color: #fff;
  background: #222;
  border: 0;
  border-radius: 0 5px 5px 0;
}

.icon-button {
  display: none;
  width: 38px;
  height: 38px;
  place-items: center;
  color: #333;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.mobile-menu-button span {
  display: block;
  width: 16px;
  height: 2px;
  margin: 2px 0;
  background: currentColor;
}

.site-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--sidebar);
  gap: var(--gap);
  max-width: var(--shell);
  padding: 28px 20px 72px;
  margin: 0 auto;
}

.site-main,
.site-sidebar { min-width: 0; }

.sidebar-sticky {
  position: sticky;
  top: calc(var(--header-h) + 18px);
  display: grid;
  gap: 14px;
}

.archive-head,
.article,
.post-card,
.sidebar-widget,
.comments-panel,
.pager {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.archive-head {
  padding: 22px 24px;
  margin-bottom: 18px;
}

.archive-head h1 {
  margin: 0;
  color: var(--text-strong);
  font-size: 24px;
  line-height: 1.35;
  letter-spacing: -0.04em;
}

.archive-head p {
  margin: 8px 0 0;
  color: var(--text-muted);
  font-size: 14px;
}

.post-list {
  display: grid;
  gap: 12px;
}

.post-card {
  display: grid;
  grid-template-columns: 168px minmax(0, 1fr);
  overflow: hidden;
}

.post-card:hover { border-color: var(--line-strong); }

.post-card__thumb {
  position: relative;
  display: block;
  min-height: 118px;
  overflow: hidden;
  background: #f0f0ec;
}

.post-card__thumb img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 0;
}

.post-card__body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 16px 18px;
}

.post-card__label {
  display: inline-flex;
  width: fit-content;
  margin-bottom: 6px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 700;
}

.post-card h2 {
  margin: 0;
  color: var(--text-strong);
  font-size: 18px;
  line-height: 1.45;
  letter-spacing: -0.03em;
}

.post-card h2 a:hover { color: var(--accent); }

.post-card p {
  display: -webkit-box;
  margin: 8px 0 0;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 14px;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.post-card__meta {
  display: flex;
  gap: 8px;
  margin-top: 10px;
  color: #8a8a8a;
  font-size: 12px;
}

.article {
  max-width: var(--content);
  padding: 32px 36px 40px;
  margin: 0 auto;
}

.article-header { padding-bottom: 20px; }

.article-label {
  display: inline-block;
  margin-bottom: 10px;
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
}

.article-header h1,
.article .post-title {
  margin: 0;
  color: var(--text-strong);
  font-size: clamp(28px, 4vw, 36px);
  font-weight: 800;
  line-height: 1.32;
  letter-spacing: -0.045em;
}

.article-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
  color: var(--text-muted);
  font-size: 13px;
}

.article-body,
.post-body {
  margin-top: 8px;
  color: #2a2a2a;
  font-size: 17.5px;
  line-height: 1.88;
  letter-spacing: -0.012em;
}

.article-body > *:first-child,
.post-body > *:first-child { margin-top: 0; }

.article-body p,
.post-body p { margin: 1.2em 0; }

.article-body a,
.post-body a {
  color: #17352f;
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: #c5d4d0;
  text-underline-offset: 0.18em;
}

.article-body a:hover,
.post-body a:hover { text-decoration-color: var(--accent); }

.article-body h2,
.post-body h2,
.article-body h3,
.post-body h3,
.article-body h4,
.post-body h4 {
  color: var(--text-strong);
  line-height: 1.4;
  letter-spacing: -0.035em;
  scroll-margin-top: calc(var(--header-h) + 16px);
}

.article-body h2,
.post-body h2 {
  padding-top: 12px;
  margin: 2.4em 0 0.7em;
  font-size: 26px;
}

.article-body h3,
.post-body h3 {
  margin: 1.8em 0 0.6em;
  font-size: 21px;
}

.article-body h4,
.post-body h4 {
  margin: 1.4em 0 0.5em;
  font-size: 18px;
}

.article-body ul,
.post-body ul,
.article-body ol,
.post-body ol {
  padding-left: 1.3em;
  margin: 1.1em 0;
}

.article-body li + li,
.post-body li + li { margin-top: 0.35em; }

.article-body blockquote,
.post-body blockquote {
  margin: 1.6em 0;
  padding: 4px 0 4px 16px;
  color: #3a3a3a;
  background: transparent;
  border-left: 3px solid var(--accent);
}

.article-body pre,
.post-body pre {
  padding: 16px;
  margin: 1.6em 0;
  overflow-x: auto;
  color: #f3f3f0;
  background: #1d1f1e;
  border-radius: 6px;
}

.article-body code,
.post-body code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.article-body :not(pre) > code,
.post-body :not(pre) > code {
  padding: 0.12em 0.35em;
  color: #8a2b2b;
  background: #f7f7f4;
  border: 1px solid var(--line);
  border-radius: 4px;
}

.article-body img,
.post-body img {
  display: block;
  margin: 1.6em auto;
  border-radius: 6px;
}

.article-body table,
.post-body table {
  width: 100%;
  margin: 1.6em 0;
  overflow-x: auto;
  border-collapse: collapse;
}

.article-body th,
.post-body th,
.article-body td,
.post-body td {
  padding: 10px 12px;
  border: 1px solid var(--line);
}

.article-body th,
.post-body th { background: #f7f7f4; }

.article-toc {
  padding: 16px 18px;
  margin: 20px 0 8px;
  background: #fafaf8;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.article-toc.is-empty { display: none; }

.article-toc__title {
  margin-bottom: 8px;
  color: #333;
  font-size: 13px;
  font-weight: 800;
}

.article-toc ol,
.mobile-toc ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

.article-toc li + li,
.mobile-toc li + li { margin-top: 2px; }

.article-toc a,
.mobile-toc a {
  display: block;
  padding: 5px 8px;
  color: #5c5c5c;
  font-size: 14px;
  line-height: 1.45;
  border-radius: 4px;
}

.article-toc a.is-active,
.article-toc a:hover,
.mobile-toc a:hover {
  color: #111;
  background: #eee;
}

.article-toc .toc-level-3 a,
.mobile-toc .toc-level-3 a {
  padding-left: 20px;
  font-size: 13px;
}

.ad-slot {
  display: grid;
  min-height: 100px;
  place-items: center;
  padding: 10px;
  margin: 20px 0;
  color: #9a9a96;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-align: center;
  background: var(--ad-bg);
  border: 1px dashed var(--ad-line);
  border-radius: 6px;
}

.ad-slot span {
  padding: 3px 7px;
  background: #fff;
  border: 1px solid #eee;
  border-radius: 4px;
}

.ad-slot[hidden] { display: none !important; }

.ad-slot--article-top,
.ad-slot--article-bottom { min-height: 250px; }

.ad-slot--article-middle {
  min-height: 280px;
  margin: 36px 0;
}

.ad-slot--sidebar {
  min-height: 250px;
  margin: 0;
}

.ad-slot--list-top,
.ad-slot--list-middle,
.ad-slot--list-bottom { min-height: 120px; }

.article-labels,
.article-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 22px;
  margin-top: 24px;
  border-top: 1px solid var(--line);
}

.article-labels a,
.tag-cloud a {
  padding: 5px 9px;
  color: #666;
  font-size: 13px;
  background: #f7f7f4;
  border: 1px solid var(--line);
  border-radius: 4px;
}

.article-actions {
  display: flex;
  gap: 8px;
  margin-top: 18px;
}

.article-actions button {
  padding: 8px 12px;
  color: #fff;
  background: #222;
  border: 0;
  border-radius: 6px;
}

.post-nav {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 22px;
}

.post-nav a {
  display: block;
  padding: 14px 16px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.post-nav span {
  display: block;
  color: #888;
  font-size: 12px;
}

.post-nav p {
  margin: 4px 0 0;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.4;
}

.post-nav .is-empty {
  color: #bbb;
  pointer-events: none;
}

.comments-panel,
.sidebar-widget { padding: 18px; }

.comments-panel { margin-top: 18px; }

.comments-panel h2,
.comments-panel h3,
.sidebar-widget h3,
.widget-title h3 {
  margin: 0 0 12px;
  color: #222;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: -0.03em;
}

.sidebar-widget ul,
.sidebar-widget ol,
.Label ul,
.PopularPosts ul,
.BlogArchive ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.sidebar-widget li + li,
.Label li + li,
.PopularPosts li + li,
.BlogArchive li + li { margin-top: 8px; }

.sidebar-widget a,
.Label a,
.PopularPosts a,
.BlogArchive a {
  color: #555;
  font-size: 14px;
  line-height: 1.45;
}

.sidebar-widget a:hover,
.Label a:hover,
.PopularPosts a:hover { color: var(--accent); }

.PopularPosts .post-thumb {
  width: 52px;
  height: 52px;
  margin-right: 10px;
  object-fit: cover;
  border-radius: 4px;
}

.PopularPosts .post {
  display: flex;
  align-items: flex-start;
}

.tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pager,
.blog-pager {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-top: 22px;
  padding: 12px;
}

.pager a,
.blog-pager a {
  min-width: 40px;
  padding: 8px 12px;
  color: #555;
  font-weight: 700;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.floating-toc-button {
  position: fixed;
  right: 16px;
  bottom: 18px;
  z-index: 850;
  display: none;
  padding: 10px 12px;
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  background: #222;
  border: 0;
  border-radius: 6px;
}

.mobile-toc[hidden],
.mobile-sticky-ad[hidden] { display: none !important; }

.mobile-toc {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: rgba(0, 0, 0, 0.4);
}

.mobile-toc__panel {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  max-height: 70vh;
  overflow: auto;
  padding: 16px;
  background: #fff;
  border-radius: 12px 12px 0 0;
}

.mobile-toc__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.mobile-toc__head button,
.mobile-sticky-ad button {
  padding: 6px 10px;
  color: #fff;
  background: #222;
  border: 0;
  border-radius: 4px;
}

.mobile-sticky-ad {
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 800;
  padding: 8px 8px 8px;
  background: #fff;
  border-top: 1px solid var(--line);
}

.site-footer {
  padding: 28px 20px 40px;
  color: #888;
  font-size: 13px;
  text-align: center;
  border-top: 1px solid var(--line);
}

.site-footer a { color: #555; }
.site-footer nav { display: flex; gap: 12px; justify-content: center; margin-top: 8px; }

.queryMessage {
  padding: 22px 24px;
  margin-bottom: 18px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.queryMessage a { margin-left: 8px; color: var(--accent); font-weight: 700; }

.errorWrap {
  padding: 48px 24px;
  text-align: center;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.index-post {
  display: grid;
  grid-template-columns: 168px minmax(0, 1fr);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.index-post:hover { border-color: var(--line-strong); }

.index-post .post-image-wrap,
.index-post .post-image-link {
  position: relative;
  display: block;
  min-height: 118px;
  overflow: hidden;
  background: #f0f0ec;
}

.index-post .post-thumb {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.index-post .post-info { padding: 16px 18px; }

.index-post .post-title {
  margin: 0;
  font-size: 18px;
  line-height: 1.45;
}

.index-post .post-snippet {
  display: -webkit-box;
  margin: 8px 0 0;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 14px;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.Header h1,
.Header .title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.Header img { max-height: 36px; width: auto; }

.PageList ul,
.PageList li { margin: 0; padding: 0; list-style: none; }

.PageList ul { display: flex; gap: 4px; }

.BlogSearch .widget-content { margin: 0; }

.widget { margin: 0; }
.site-nav .widget-content,
.header-actions .widget-content,
.brand .widget-content { margin: 0; padding: 0; }
.site-nav .widget,
.header-actions .widget { display: block; }

#ad-sources { display: none; }
.ad-template { display: none !important; }
body#layout #ad-sources {
  display: grid;
  gap: 12px;
  max-width: 1080px;
  padding: 20px;
  margin: 0 auto;
}
body#layout #ad-sources .widget {
  padding: 12px;
  background: #fff;
  border: 1px dashed #ccc;
}

.comment { padding: 14px 0; border-top: 1px solid var(--line); }
.comment-author { font-weight: 700; }
.comment-body { margin-top: 6px; }
.comment-footer { margin-top: 6px; color: #888; font-size: 12px; }
.avatar-image-container img { border-radius: 50%; }

.navbar,
#navbar-iframe,
.widget-item-control,
.home-link,
.feed-links { display: none !important; }

body#layout .site-header,
body#layout .site-shell { position: static; }
body#layout .ad-slot { min-height: 80px; }

@media (max-width: 980px) {
  .site-shell {
    grid-template-columns: 1fr;
    padding-bottom: 88px;
  }

  .sidebar-sticky { position: static; }

  .icon-button.mobile-menu-button { display: grid; }

  .site-nav {
    position: absolute;
    top: var(--header-h);
    right: 0;
    left: 0;
    display: none;
    padding: 10px 16px 16px;
    background: #fff;
    border-bottom: 1px solid var(--line);
  }

  .site-nav.is-open { display: block; }

  .site-nav ul { flex-direction: column; align-items: stretch; }

  .floating-toc-button { display: inline-flex; }

  .article { padding: 22px 18px 28px; }

  .article-body,
  .post-body {
    font-size: 16.5px;
    line-height: 1.86;
  }

  .ad-slot--article-top,
  .ad-slot--article-bottom,
  .ad-slot--article-middle { min-height: 100px; }
}

@media (max-width: 720px) {
  .search-form { width: 42vw; min-width: 132px; }

  .post-card,
  .index-post { grid-template-columns: 108px minmax(0, 1fr); }

  .post-card__thumb,
  .index-post .post-image-wrap { min-height: 88px; }

  .post-card__body { padding: 12px 12px 12px 0; }

  .post-card h2 { font-size: 16px; }

  .post-card p,
  .index-post .post-snippet { display: none; }

  .post-nav { grid-template-columns: 1fr; }
}

body.script:
//
window.sugarcoatConfig = {
  articleMiddleAdAfterHeading: 2,
  listAdAfterItem: 4,
  showAdPlaceholders: false,
  enableMobileStickyAd: false
};
//

  //
(function () {
  "use strict";

  var config = window.sugarcoatConfig || {};
  var afterHeading = Number(config.articleMiddleAdAfterHeading || 2);
  var listAfter = Number(config.listAdAfterItem || 4);
  var showPlaceholders = Boolean(config.showAdPlaceholders);
  var enableSticky = Boolean(config.enableMobileStickyAd);

  function ready(fn) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else {
      fn();
    }
  }

  function slugify(text, index) {
    var slug = String(text || "")
      .trim()
      .toLowerCase()
      .replace(/[^\w\u3131-\u318e\uac00-\ud7a3\s-]/g, "")
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-");
    return slug || "section-" + index;
  }

  function uniqueId(base) {
    var id = base;
    var n = 2;
    while (document.getElementById(id)) {
      id = base + "-" + n;
      n += 1;
    }
    return id;
  }

  function initMenu() {
    var button = document.querySelector("[data-menu-toggle]");
    var nav = document.querySelector("[data-site-nav]");
    if (!button || !nav) return;

    button.addEventListener("click", function () {
      var open = nav.classList.toggle("is-open");
      button.setAttribute("aria-expanded", String(open));
    });

    document.addEventListener("click", function (event) {
      if (!nav.classList.contains("is-open")) return;
      if (nav.contains(event.target) || button.contains(event.target)) return;
      nav.classList.remove("is-open");
      button.setAttribute("aria-expanded", "false");
    });
  }

  function initProgress() {
    var bar = document.querySelector(".reading-progress span");
    var article = document.querySelector("[data-article-body], .post-body");
    if (!bar || !article) return;

    function update() {
      var rect = article.getBoundingClientRect();
      var total = Math.max(article.offsetHeight - window.innerHeight, 1);
      var read = Math.min(Math.max(-rect.top, 0), total);
      bar.style.width = (read / total) * 100 + "%";
    }

    update();
    window.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update, { passive: true });
  }

  function initToc() {
    var article = document.querySelector("[data-article-body], .item-post .post-body");
    var toc = document.querySelector("[data-toc]");
    var tocList = document.querySelector("[data-toc-list]");
    var mobileToc = document.querySelector("[data-mobile-toc]");
    var mobileList = document.querySelector("[data-mobile-toc-list]");
    if (!article || !tocList || !mobileList) return;

    var headings = Array.prototype.slice.call(article.querySelectorAll("h2, h3"));
    if (headings.length < 2) {
      if (toc) toc.classList.add("is-empty");
      var floating = document.querySelector("[data-mobile-toc-toggle]");
      if (floating) floating.hidden = true;
      return;
    }

    var seen = {};
    headings.forEach(function (heading, index) {
      if (!heading.id) heading.id = uniqueId(slugify(heading.textContent, index + 1));
      else if (seen[heading.id]) heading.id = uniqueId(heading.id);
      seen[heading.id] = true;

      var li = document.createElement("li");
      li.className = "toc-level-" + heading.tagName.slice(1);
      var link = document.createElement("a");
      link.href = "#" + heading.id;
      link.textContent = heading.textContent.trim();
      li.appendChild(link);
      tocList.appendChild(li);
      mobileList.appendChild(li.cloneNode(true));
    });

    var links = Array.prototype.slice.call(document.querySelectorAll("[data-toc-list] a, [data-mobile-toc-list] a"));
    if ("IntersectionObserver" in window) {
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (!entry.isIntersecting) return;
          links.forEach(function (link) {
            link.classList.toggle("is-active", link.getAttribute("href") === "#" + entry.target.id);
          });
        });
      }, { rootMargin: "-18% 0px -72% 0px", threshold: 0.01 });
      headings.forEach(function (heading) { observer.observe(heading); });
    }

    initMobileToc(mobileToc);
  }

  function initMobileToc(mobileToc) {
    var openButton = document.querySelector("[data-mobile-toc-toggle]");
    var closeButton = document.querySelector("[data-mobile-toc-close]");
    if (!mobileToc || !openButton || !closeButton) return;

    function open() {
      mobileToc.hidden = false;
      document.body.style.overflow = "hidden";
    }

    function close() {
      mobileToc.hidden = true;
      document.body.style.overflow = "";
    }

    openButton.addEventListener("click", open);
    closeButton.addEventListener("click", close);
    mobileToc.addEventListener("click", function (event) {
      if (event.target === mobileToc || event.target.tagName === "A") close();
    });
    document.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && !mobileToc.hidden) close();
    });
  }

  function cloneTemplateChild(template) {
    if (!template) return null;
    if (template.content && template.content.firstElementChild) {
      return template.content.firstElementChild.cloneNode(true);
    }
    var child = template.querySelector(".ad-slot");
    return child ? child.cloneNode(true) : null;
  }

  function slotHasAdContent(slot) {
    var clone = slot.cloneNode(true);
    Array.prototype.forEach.call(clone.querySelectorAll("span.ad-label, .ad-label"), function (label) {
      label.remove();
    });
    var text = clone.textContent.replace(/\s+/g, "").trim();
    var hasAdElement = Boolean(clone.querySelector("ins.adsbygoogle, iframe, script, [data-ad-client], [data-ad-slot]"));
    return Boolean(text) || hasAdElement;
  }

  function hideEmptyAdSlots() {
    if (showPlaceholders) return;
    Array.prototype.forEach.call(document.querySelectorAll(".ad-slot"), function (slot) {
      if (!slotHasAdContent(slot)) {
        slot.hidden = true;
        slot.setAttribute("aria-hidden", "true");
      }
    });
  }

  function hasInsertedAutoAd(root, kind) {
    if (!root) return false;
    var nodes = root.querySelectorAll('[data-auto-ad="' + kind + '"]');
    for (var i = 0; i < nodes.length; i += 1) {
      if (!nodes[i].closest || !nodes[i].closest(".ad-template")) return true;
    }
    return false;
  }

  function insertArticleMiddleAd() {
    var article = document.querySelector("[data-article-body], .item-post .post-body");
    var template = document.getElementById("article-middle-ad-template");
    if (!article || !template || hasInsertedAutoAd(article, "middle")) return;

    var headings = Array.prototype.slice.call(article.querySelectorAll("h2"));
    var anchor = headings[Math.max(afterHeading - 1, 0)];
    if (!anchor) {
      var paragraphs = Array.prototype.slice.call(article.querySelectorAll("p"));
      anchor = paragraphs[Math.floor(paragraphs.length / 2)];
    }
    var node = cloneTemplateChild(template);
    if (!anchor || !node) return;
    anchor.insertAdjacentElement("afterend", node);
  }

  function insertListAd() {
    var list = document.querySelector("[data-post-list], .post-list");
    var template = document.getElementById("list-ad-template");
    if (!list || !template || hasInsertedAutoAd(list, "list")) return;
    var cards = Array.prototype.slice.call(list.querySelectorAll(".post-card, .index-post"));
    var anchor = cards[Math.max(listAfter, 1) - 1];
    var node = cloneTemplateChild(template);
    if (!anchor || !node) return;
    anchor.insertAdjacentElement("afterend", node);
  }

  function moveBloggerAds() {
    var map = [
      ["ad-article-top", ".ad-slot--article-top"],
      ["ad-article-bottom", ".ad-slot--article-bottom"],
      ["ad-sidebar", ".ad-slot--sidebar"],
      ["ad-list-top", ".ad-slot--list-top"],
      ["ad-list-bottom", ".ad-slot--list-bottom"],
      ["ad-mobile-sticky", ".ad-slot--mobile-sticky"]
    ];

    map.forEach(function (pair) {
      var source = document.getElementById(pair[0]);
      var target = document.querySelector(pair[1]);
      if (!source || !target) return;
      var content = source.querySelector(".widget-content");
      if (!content) return;
      var html = content.innerHTML.trim();
      if (!html) return;
      target.insertAdjacentHTML("beforeend", html);
    });

    var middleSource = document.getElementById("ad-article-middle");
    var middleTemplate = document.getElementById("article-middle-ad-template");
    fillTemplateSlot(middleSource, middleTemplate);

    var listSource = document.getElementById("ad-list-middle");
    var listTemplate = document.getElementById("list-ad-template");
    fillTemplateSlot(listSource, listTemplate);
  }

  function fillTemplateSlot(source, template) {
    if (!source || !template) return;
    var content = source.querySelector(".widget-content");
    if (!content || !content.innerHTML.trim()) return;
    var slot = (template.content && template.content.querySelector(".ad-slot")) || template.querySelector(".ad-slot");
    if (slot) slot.insertAdjacentHTML("beforeend", content.innerHTML);
  }

  function initMobileStickyAd() {
    var wrapper = document.querySelector("[data-mobile-sticky-ad]");
    var closeButton = document.querySelector("[data-mobile-ad-close]");
    if (!wrapper || !enableSticky) return;
    wrapper.hidden = false;
    if (sessionStorage.getItem("sugarcoat-sticky-closed") === "1") {
      wrapper.hidden = true;
      return;
    }
    if (closeButton) {
      closeButton.addEventListener("click", function () {
        wrapper.hidden = true;
        sessionStorage.setItem("sugarcoat-sticky-closed", "1");
      });
    }
  }

  function initArticleEnhancements() {
    var article = document.querySelector("[data-article-body], .post-body");
    if (!article) return;

    Array.prototype.forEach.call(article.querySelectorAll("img"), function (img, index) {
      if (index > 0 && !img.hasAttribute("loading")) img.loading = "lazy";
      if (!img.hasAttribute("decoding")) img.decoding = "async";
    });

    Array.prototype.forEach.call(article.querySelectorAll('a[href^="http"]'), function (link) {
      if (link.hostname && link.hostname !== window.location.hostname) {
        link.rel = "noopener noreferrer";
        link.target = "_blank";
      }
    });
  }

  function initShare() {
    var copyButton = document.querySelector("[data-copy-link]");
    var shareButton = document.querySelector("[data-native-share]");

    if (copyButton) {
      copyButton.addEventListener("click", function () {
        var url = window.location.href;
        function done() {
          copyButton.textContent = "복사 완료";
          setTimeout(function () { copyButton.textContent = "링크 복사"; }, 1600);
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(url).then(done).catch(function () {
            fallbackCopy(url);
            done();
          });
        } else {
          fallbackCopy(url);
          done();
        }
      });
    }

    if (shareButton) {
      shareButton.addEventListener("click", function () {
        if (navigator.share) {
          navigator.share({ title: document.title, url: window.location.href }).catch(function () {});
        } else if (copyButton) {
          copyButton.click();
        }
      });
    }
  }

  function fallbackCopy(text) {
    var textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.setAttribute("readonly", "");
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    try { document.execCommand("copy"); } catch (e) {}
    textarea.remove();
  }

  ready(function () {
    initMenu();
    initProgress();
    initToc();
    moveBloggerAds();
    insertArticleMiddleAd();
    insertListAd();
    hideEmptyAdSlots();
    initMobileStickyAd();
    initArticleEnhancements();
    initShare();
  });
})();

  //
